import { activeChanged, selectedChanged } from "./video-rendition-list.js";
//#region src/core/media-tracks/video-rendition.ts
/**
* The consumer should use the `selected` setter to select one or multiple renditions that the engine is allowed to
* play.
*
* @internal
*/
var VideoRendition = class {
	src;
	id;
	width;
	height;
	bitrate;
	frameRate;
	codec;
	#selected = false;
	#active = false;
	get selected() {
		return this.#selected;
	}
	set selected(value) {
		if (this.#selected === value) return;
		this.#selected = value;
		selectedChanged(this);
	}
	get active() {
		return this.#active;
	}
	set active(value) {
		if (this.#active === value) return;
		this.#active = value;
		activeChanged(this);
	}
};
//#endregion
export { VideoRendition };
